package com.nexaflow.feature.settings

/**
 * Conservative comparison boundary between a GitHub release tag and the
 * installed `versionName` generated by GitVersion.
 *
 * A malformed, unknown, equal, or older remote version is never considered an
 * update. This fail-closed policy prevents a release such as `v3.38.8` from
 * prompting an installation when the app already reports `3.38.8`, or when a
 * development build is already based on that tagged release.
 */
object UpdateVersion {

    /**
     * The single decision boundary for the manual checker and the periodic
     * notification worker. A remote release is offered only when it is proven
     * newer than the installed release; equality is rejected explicitly before
     * ordering so a leading `v` can never produce a false update prompt.
     */
    fun shouldOfferUpdate(remote: String, installed: String): Boolean {
        val remoteVersion = parse(remote) ?: return false
        val installedVersion = parse(installed) ?: return false
        if (remoteVersion.canonical == installedVersion.canonical) return false
        return remoteVersion > installedVersion
    }

    /** Backward-compatible name for callers that used the prior API. */
    fun isStrictlyNewer(remote: String, installed: String): Boolean =
        shouldOfferUpdate(remote, installed)

    /** True only when both strings positively identify the same release. */
    fun isSameRelease(first: String, second: String): Boolean {
        val firstCanonical = canonical(first) ?: return false
        val secondCanonical = canonical(second) ?: return false
        return firstCanonical == secondCanonical
    }

    /** Canonical display form used for equality and notification de-duplication. */
    fun canonical(value: String): String? = parse(value)?.canonical

    private fun parse(value: String): ParsedVersion? {
        val raw = value.trim()
        val match = VERSION_PATTERN.matchEntire(raw) ?: return null
        val major = match.groupValues[1].toIntOrNull() ?: return null
        val minor = match.groupValues[2].toIntOrNull() ?: return null
        val patch = match.groupValues[3].toIntOrNull() ?: return null
        val suffix = match.groupValues[4].takeIf { it.isNotBlank() }
        return ParsedVersion(major, minor, patch, suffix)
    }

    private data class ParsedVersion(
        val major: Int,
        val minor: Int,
        val patch: Int,
        val suffix: String?
    ) : Comparable<ParsedVersion> {

        val canonical: String = "$major.$minor.$patch" + suffix?.let { "-$it" }.orEmpty()

        /** Git describes a commit after a tag as `tag-distance-g<hash>`. */
        private val isPostReleaseCommit: Boolean = suffix?.matches(POST_RELEASE_SUFFIX) == true
        private val isStable: Boolean = suffix == null

        override fun compareTo(other: ParsedVersion): Int {
            compareValuesBy(this, other, ParsedVersion::major, ParsedVersion::minor, ParsedVersion::patch)
                .takeIf { it != 0 }
                ?.let { return it }

            // A build made after the current release tag must not be prompted to
            // install the same tagged APK. It is already ahead of that artifact.
            if (isPostReleaseCommit != other.isPostReleaseCommit) {
                return if (isPostReleaseCommit) 1 else -1
            }
            if (isStable != other.isStable) {
                return if (isStable) 1 else -1
            }
            return comparePrerelease(suffix, other.suffix)
        }

        private fun comparePrerelease(left: String?, right: String?): Int {
            if (left == right) return 0
            if (left == null) return 1
            if (right == null) return -1
            val leftParts = left.split('-', '.').filter { it.isNotBlank() }
            val rightParts = right.split('-', '.').filter { it.isNotBlank() }
            val limit = minOf(leftParts.size, rightParts.size)
            repeat(limit) { index ->
                val a = leftParts[index]
                val b = rightParts[index]
                if (a == b) return@repeat
                val aNumber = a.toLongOrNull()
                val bNumber = b.toLongOrNull()
                return when {
                    aNumber != null && bNumber != null -> aNumber.compareTo(bNumber)
                    aNumber != null -> -1
                    bNumber != null -> 1
                    else -> a.compareTo(b, ignoreCase = true)
                }
            }
            return leftParts.size.compareTo(rightParts.size)
        }
    }

    private val VERSION_PATTERN = Regex(
        "^v?(\\d+)\\.(\\d+)\\.(\\d+)(?:-([0-9A-Za-z.-]+))?$"
    )
    private val POST_RELEASE_SUFFIX = Regex("\\d+-g[0-9a-fA-F]+")
}
